svg.script:
(() => {
  const svg = document.documentElement;
  const { layer, nets } = JSON.parse(document.getElementById("wiring").textContent);
  const byId = new Map(nets.map(net => [net.id, net]));
  const wires = document.getElementById(layer);
  const marks = document.getElementById("wire-endpoints");
  const status = document.getElementById("wire-status");
  const paths = [...wires.querySelectorAll("[data-net]")];
  const primary = paths.filter(path => path.hasAttribute("data-wire-hit"));
  const hint = "点按导线查看端点 · 按 Esc 清除";
  const make = tag => document.createElementNS(svg.namespaceURI, tag);
  const focusable = new Set();
  let flashTimer;

  const title = net => net.endpoints.map(({ device, pin }) => device + " " + pin).join(" ↔ ");
  function select(id) {
    const net = byId.get(id);
    for (const path of paths) {
      path.classList.toggle("wire-muted", !!net && path.dataset.net !== id);
      path.classList.toggle("wire-selected", !!net && path.dataset.net === id);
    }
    status.textContent = net ? net.name + " · " + title(net) : hint;
    marks.replaceChildren();
    window.clearTimeout(flashTimer);
    if (!net) return;
    for (const { x, y } of net.endpoints) {
      const circle = make("circle");
      circle.setAttribute("cx", x);
      circle.setAttribute("cy", y);
      circle.setAttribute("r", "8");
      circle.setAttribute("class", "wire-endpoint");
      marks.append(circle);
    }
    flashTimer = window.setTimeout(() => marks.replaceChildren(), 450);
  }

  // Broad touch targets are below all centerlines so close parallel wires remain selectable.
  for (const width of [14, 4]) {
    const targets = make("g");
    for (const path of primary) {
      const hit = path.cloneNode(false);
      hit.removeAttribute("id");
      hit.removeAttribute("data-net");
      hit.removeAttribute("data-wire-hit");
      hit.setAttribute("class", "wire-hit");
      hit.dataset.hitNet = path.dataset.net;
      hit.setAttribute("stroke-width", width);
      if (width === 4 && !focusable.has(hit.dataset.hitNet)) {
        focusable.add(hit.dataset.hitNet);
        hit.setAttribute("tabindex", "0");
        hit.setAttribute("role", "button");
        hit.setAttribute("aria-label", title(byId.get(hit.dataset.hitNet)));
      }
      targets.append(hit);
    }
    wires.append(targets);
  }
  svg.setAttribute("role", "group");
  svg.addEventListener("click", event => select(event.target.dataset?.hitNet));
  svg.addEventListener("keydown", event => {
    if (event.key === "Escape") select();
    if ((event.key === "Enter" || event.key === " ") && event.target.dataset?.hitNet) {
      event.preventDefault();
      select(event.target.dataset.hitNet);
    }
  });
  status.textContent = hint;
})();
